import { CourseVideoView } from "@/components/course-video-view";

type PageContext = { params: Promise<{ courseId: string; artifactId: string }> };

/**
 * Course-level render view for teaching videos generated by the course
 * chat. Video artifacts live at course scope (`notebook_id` null) and open
 * from the sidebar Videos group under their course.
 */
export default async function CourseVideoPage({ params }: PageContext) {
  const { courseId, artifactId } = await params;
  // Key by route ids so navigating between videos never shows stale data
  // from the previously viewed video.
  return <CourseVideoView key={`${courseId}:${artifactId}`} courseId={courseId} artifactId={artifactId} />;
}
